const icons={arrow:'<path d="M4 12h15M13 5l7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',menu:'<path d="M4 8h16M4 16h16"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8l9-5ZM3 8l9 5 9-5M12 13v9M7 5.8l9 5"/>',bike:'<circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="m5 17 5-10 5 10H5l7-7h5l2 7M8 7h5M16 4h2l2 4"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3V7Z"/><circle cx="12" cy="13" r="4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',wallet:'<path d="M3 6h17v14H3V6Zm0 0 14-3v3M16 11h5v5h-5v-5Z"/>',chat:'<path d="M21 11a9 9 0 0 1-13 8L3 21l2-5A9 9 0 1 1 21 11Z"/><path d="M8 9h8M8 13h5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',store:'<path d="M4 10v11h16V10M3 10l2-7h14l2 7M3 10a3 3 0 0 0 6 0 3 3 0 0 0 6 0 3 3 0 0 0 6 0M9 21v-7h6v7"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 5h4M11 19h2"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',team:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 8M18 15a5 5 0 0 1 4 5v1"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v5M17 3v5M3 11h18M7 15h3M14 15h3"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 4v6h6"/>',send:'<path d="m3 3 18 9-18 9 4-9-4-9ZM7 12h14"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',external:'<path d="M8 4H4v16h16v-4M13 3h8v8M10 14 21 3"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
const logo=()=>`<a class="logo" href="/" aria-label="Ada home">Ada</a>`;
const orb=(large=false)=>`<span class="orb${large?' large':''}" aria-hidden="true"></span>`;
const photo=(cls='',alt='Cartoon illustration of a courier handing a parcel to a customer',source='delivery-day-rider.webp')=>`<img class="campaign ${cls}" src="/marketing/assets/${source}" alt="${alt}" loading="lazy" width="1536" height="1024">`;
const btn=(text,href='/get-started',cls='',attrs='')=>`<a class="btn ${cls}" href="${href}" ${attrs}>${text} ${icon('arrow')}</a>`;
const link=(text,href)=>`<a class="text-link" href="${href}">${text} ${icon('arrow')}</a>`;
const wave=(word)=>`<span class="underline">${word}<svg viewBox="0 0 400 20" preserveAspectRatio="none" aria-hidden="true"><path d="M2 13C80 3 235 1 397 11M25 18C140 11 265 11 365 17"/></svg></span>`;
const list=(items)=>`<ul class="check-list">${items.map(t=>`<li>${icon('check')}<span>${t}</span></li>`).join('')}</ul>`;
const routes=[['For companies','/for-companies'],['For vendors','/for-vendors'],['For riders','/for-riders'],['Meet Ada','/ada'],['How it works','/how-it-works'],['WhatsApp','/whatsapp'],['Proof of delivery','/proof-of-delivery'],['Pricing','/pricing'],['Questions','/questions'],['Book a demo','/book-a-demo']];
const faq=[
 ['Who signs up first?','The delivery company signs up first. It adds its vendors, riders and office teammates, then shares a separate invite code or link with each person. Vendors and riders join the company’s account.'],
 ['Do riders and vendors need to install an app?','No. They can use Ada in a phone browser or work with Ada on WhatsApp when the company connects its WhatsApp Business number. Add Ada to the home screen for a full-screen experience. Android and iPhone store apps are on the way.'],
 ['Does Ada dispatch without asking me?','No. Ada reads orders, checks information and drafts the stock changes, rider batches and messages. A person reviews the plan and taps Approve & send before those changes are saved.'],
 ['What counts as proof of delivery?','The rider captures a doorstep photo, the recipient, the exact amount collected and whether it was cash, transfer or POS. Ada adds the timestamp and makes the record visible to the office and the relevant vendor.'],
 ['Can one vendor see another vendor’s sales?','No. Every vendor has a separate login and sees only their own products, orders, deliveries and money. Riders see their own drops. The company controls its workspace.'],
 ['What happens when a delivery fails?','The rider records the problem. The drop is marked as not delivered and its units return to the warehouse count. The office can follow up and plan another delivery.'],
 ['Is a delivered order also a verified payment?','No. Stock and money are tracked separately. A delivered order reduces stock left, but its payment stays under Payment to verify until the office checks that the money landed. Bank and POS auto-verification are not currently available.'],
 ['How does WhatsApp work?','The company connects an official WhatsApp Business number through Meta Cloud API or Twilio. Ada sends rider batches and vendor updates and reads supported replies. Office staff can step in on any chat. Before connecting a number, the app includes a test-line simulator.'],
 ['How long does setup take?','The company’s initial setup is designed to take about five minutes. Add your company details and areas, then invite riders and vendors. Connecting a WhatsApp Business number is a separate setup step.'],
 ['How much does Ada cost?','Pricing has not been finalised. We’ll share clear plans when they’re ready. Get started free to explore the product, or plan a walkthrough around your operation.']
];
function faqMarkup(items=faq){return `<div class="faq-list">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`}
function header(){return `<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="header-inner">${logo()}<nav class="desktop-nav" aria-label="Main navigation"><div class="nav-item"><button class="nav-trigger" aria-expanded="false">Who it’s for ${icon('down')}</button><div class="dropdown"><a href="/for-companies">For delivery companies<small>Your operation, on one live screen.</small></a><a href="/for-vendors">For vendors<small>Your stock, drops and money.</small></a><a href="/for-riders">For riders<small>A clearer day on the road.</small></a></div></div><a href="/how-it-works">How it works</a><a href="/ada">Meet Ada</a><a href="/pricing">Pricing</a><a href="/book-a-demo">Book a demo</a></nav><div class="header-actions"><a class="signin" href="/signin" data-testid="nav-signin">Sign in</a>${btn('Get started','/get-started','', 'data-testid="nav-get-started"')}<button class="menu-toggle" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button></div></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div class="footer-brand">${logo()}<p>Live logistics for the vendors,<br>riders and office that move your city.</p></div><div class="footer-col"><h4>One operation</h4><a href="/for-companies">For companies</a><a href="/for-vendors">For vendors</a><a href="/for-riders">For riders</a><a href="/how-it-works">How it works</a></div><div class="footer-col"><h4>The everyday details</h4><a href="/ada">Meet Ada</a><a href="/whatsapp">Ada on WhatsApp</a><a href="/proof-of-delivery">Proof of delivery</a><a href="/demo">Try the product demo</a></div><div class="footer-col"><h4>Your next move</h4><a href="/get-started">Get started free</a><a href="/join">Join with an invite</a><a href="/pricing">Pricing</a><a href="/book-a-demo">Book a demo</a><a href="/questions">Questions & answers</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Ada. Every delivery, live for everyone.</span><div><span>Built for Nigerian delivery.</span><a href="/privacy">Privacy & this preview</a><a href="/signin">Sign in ${icon('external').replace('<svg','<svg style="width:10px;height:10px;vertical-align:middle"')}</a></div></div></div></footer>`}
function closing(){return `<section class="closing"><div class="wrap">${orb(true)}<h2>Run tomorrow’s deliveries<br> on Ada.</h2><p>A calmer office. Clearer drops. Everyone looking at the same day.</p><div class="actions">${btn('Get started free','/get-started')}${btn('Book a demo','/book-a-demo','outline')}</div><a class="closing-invite" href="/join">Already invited? Join your company →</a><span class="small-note">Company setup in about five minutes. Vendors and riders join by invitation.</span></div></section>`}
function windowPreview(){return `<div class="product-window" aria-label="Illustrative company dashboard with sample deliveries"><div class="window-head"><span class="window-logo">${icon('box')}Ada</span><span class="avatar">GO</span></div><div class="window-body"><div class="window-title">Your day, in view. <span class="live">Live</span></div><div class="preview-greeting"><small>GOOD MORNING, GEORGE</small><span>You’ve sold</span> ₦1,284,000<br><span>and</span> 312 units <span>are left.</span></div><div class="mini-metrics"><div><b>24</b><small>Delivered</small></div><div><b>12</b><small>With riders</small></div><div><b>₦206k</b><small>To collect</small></div></div><div class="mini-row"><div class="mini-person"><span class="avatar">AE</span><div><b>Ada Eze</b><small>Ikeja · GlowSkin</small></div></div><span class="status">${icon('check').replace('<svg','<svg style="width:10px;height:10px"')} Delivered</span></div><div class="mini-row"><div class="mini-person"><span class="avatar">KA</span><div><b>Kemi Ade</b><small>Yaba · Urban Finds</small></div></div><span class="status blue">On the way</span></div><div class="ada-mini">${orb()}<span>Let Ada help you…</span>${icon('spark').replace('<svg','<svg style="width:15px;height:15px"')}</div></div></div>`}
function adaCard(){return `<div class="ada-conversation"><div class="ada-id">${orb()}<div>Ada, your dispatch assistant<small>YOU SAY IT. Ada PLANS IT.</small></div></div><div class="chat-bubble you">GlowSkin dropped 40 serums at ₦12,500 each. Dispatch today’s orders.</div><div class="chat-bubble ada"><span class="chat-label">Ada · SAMPLE PLAN</span>Stock received. Here’s the plan for you to review.<div class="draft-list"><div><b>40</b>serums received</div><div><b>6</b>deliveries</div><div><b>3</b>rider batches</div><div><b>₦206,000</b>to collect</div></div><button class="approve" data-action="approve-preview">Approve & send ${icon('arrow')}</button></div><p class="approval-note">Nothing is saved until you approve. This is a sample interaction.</p></div>`}
function waPhone(mode='rider'){return `<div class="whatsapp-phone"><div class="phone-top"><span>9:41</span><span class="phone-camera"></span><span>5G ▰</span></div><div class="wa-head">${icon('down').replace('<svg','<svg style="width:12px;height:12px;transform:rotate(90deg)"')}${orb()}<div>Ada · Ada<small>Dispatch assistant</small></div></div><div class="wa-body" id="wa-messages"><div class="wa-date">TODAY · ILLUSTRATIVE CONVERSATION</div>${mode==='vendor'?`<div class="wa-message sent">Ada Eze, 5 Ajao Road, Ikeja. 2 serums. ₦25,000. 08012345678<br><br>Kemi, Yaba. 1 serum. ₦12,500.<small>09:01 ✓✓</small></div><div class="wa-message">2 orders read. Kemi’s order needs a phone number. I’ve kept it in Orders to fix.<small>09:01</small></div><div class="wa-message sent">BALANCE<small>09:02 ✓✓</small></div><div class="wa-message">Your stock, deliveries and payable balance are ready in your vendor view.<small>09:02</small></div>`:`<div class="wa-message">Morning Tunde. You have a new batch: 3 drops around Ikeja. Ready to take it?<small>08:42</small></div><div class="wa-message sent">YES<small>08:43 ✓✓</small></div><div class="wa-message">Accepted. Collect your parcels at the office. I’ll keep your next drop ready.<small>08:43</small></div><div class="wa-message sent">ARRIVED<small>10:24 ✓✓</small></div><div class="wa-message">You’re at Ada’s stop. Open the secure link to add the doorstep photo and payment.<small>10:24</small></div>`}</div><div class="wa-input"><div>Message Ada</div>${icon('send')}</div></div>`}
function proofCard(){return `<div class="proof-card"><div class="proof-photo">${photo('','Illustrated parcel handover used as sample doorstep proof')}<span class="status">${icon('check').replace('<svg','<svg style="width:13px;height:13px"')} Delivered · 10:24 AM</span></div><div class="proof-info"><h4>Ada’s order. Accounted for.</h4><p>DLV–1042 · GlowSkin · Sample delivery</p><div class="proof-lines"><div><span>Delivered by</span><b>Tunde Bakare</b></div><div><span>Received by</span><b>Ada Eze</b></div><div><span>Amount collected</span><b>₦25,000</b></div><div><span>Payment method</span><b>Cash</b></div></div><div class="payment-check">Payment to verify<br>The delivery is complete. The office checks the money separately.</div></div></div>`}
function calendar(){return `<div class="calendar-record"><h4>Your day has a memory.</h4><div class="week">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((d,i)=>`<div class="${i===2?'active':''}">${d}<b>${16+i}</b></div>`).join('')}</div><div class="record-line"><span>08:42</span><div><b>Batch approved for Tunde</b><small>3 stops · Ikeja · Sent on WhatsApp</small></div></div><div class="record-line"><span>10:24</span><div><b>Ada Eze · Delivered</b><small>Doorstep photo · ₦25,000 cash</small></div></div><div class="record-line"><span>17:06</span><div><b>Cash handed in</b><small>Office checks and verifies payment</small></div></div><div class="record-line"><span>17:30</span><div><b>Vendor settlement recorded</b><small>Per-order breakdown, kept with the day</small></div></div><p class="small-note" style="margin:15px 0 0;font-size:9px">Sample day record. Each role sees only their own part.</p></div>`}
function demoInvite(){return `<section class="wrap section-tight" id="try"><div class="demo-panel"><div><span class="eyebrow">Don’t just read about it</span><h3>One drop.<br>Three points of view.</h3><p>Try a sample delivery as the office, the vendor, or the rider. Confirm the drop and see the same record change.</p><span class="small-note" style="color:#8995bb">Interactive demo · Sample data · No account needed</span></div><div class="role-options">${[['company','grid','As the company','See the whole day. Verify the money.'],['vendor','store','As a vendor','Follow your stock, drops and balance.'],['rider','bike','As a rider','Accept a batch. Confirm the doorstep.']].map(([r,i,t,s])=>`<a class="role-option" href="/demo?role=${r}" data-testid="demo-${r}"><span>${icon(i)}<span><b>${t}</b><small>${s}</small></span></span>${icon('arrow')}</a>`).join('')}</div></div></section>`}
function audienceCards(){return `<div class="audience-grid">${[['company','The company','Less chasing. More delivering. Bring every vendor, rider and payment into one place.','Your operation, connected','/for-companies'],['vendor','The vendor','Know what left the shelf, what reached the door, and what you’re owed.','Every parcel, in view','/for-vendors'],['rider','The rider','A clear batch. One drop at a time. Your pay and hand-ins, always on record.','A clearer day on the road','/for-riders']].map(([r,t,p,l,h])=>`<article class="audience-card"><a class="audience-picture ${r}" href="${h}" aria-label="${l}">${photo('','Cartoon delivery story for '+t,r==='company'?'delivery-day-ada.webp':r==='rider'?'delivery-day-rider.webp':'delivery-day-rider.webp')}<span class="photo-label">${t}</span></a><h3>${l}</h3><p>${p}</p>${link(`For ${r==='company'?'delivery companies':r+'s'}`,h)}</article>`).join('')}</div>`}
function home(){return `<section class="hero hero-human"><div class="wrap"><div class="hero-human-copy"><span class="eyebrow">One delivery day. Everyone connected.</span><h1>Every delivery,<br>live for ${wave('everyone.')}</h1><p>Your office. Your vendors. Your riders.<br>One shared day. A whole lot less chasing.</p><div class="actions">${btn('Get started free','/get-started','', 'data-testid="hero-get-started"')}${btn('See it in action','/demo','outline')}</div></div><div class="hero-art"><img src="/marketing/assets/delivery-illustration.webp" alt="Playful original illustration of a vendor, dispatch rider and dispatcher moving parcels together" fetchpriority="high" width="1536" height="1024"><div class="art-tag tag-left">${icon('box')}Stock is in.</div><div class="art-tag tag-right">${icon('check')}Everyone’s in the loop.</div></div></div></section>${landingRest()}`}
function stockExample(){return `<div class="financial"><div class="financial-top"><h3>GlowSkin, at a glance.</h3><span>Illustrative stock example · 40 serums received</span></div><div class="stock-grid"><div><b>40</b><span>Received</span><small>Counted in by the office</small></div><div><b style="color:var(--green)">22</b><span>Delivered</span><small>Photo and payment captured</small></div><div><b style="color:var(--blue)">6</b><span>With riders</span><small>On their way to a doorstep</small></div><div><b>18</b><span>Left</span><small>12 in warehouse + 6 with riders</small></div></div><div class="ledger-bar" aria-label="22 delivered, 6 with riders, 12 in warehouse"><span></span><span></span><span></span></div><div class="finance-footer"><span>Delivered + with riders + in warehouse = received.</span><span>Payment verification is tracked separately.</span></div></div>`}
const audienceData={
 '/for-companies':{role:'company',label:'For delivery companies',title:'Your operation.<br>All together.',intro:'You have the riders, the vendors and the ambition. Ada connects the daily work so you can run the business with a clearer head.',action:'Sign up your company',href:'/signup/company',sub:'From “who has what?” to one live answer.',features:[['The morning, already in view.','Open Today to see orders to fix, rider batches, failed drops and money that needs you. Know where to focus before the calls start.'],['Dispatch with a conversation.','Tell Ada what stock arrived or paste your WhatsApp orders. Review rider batches by area and remaining allocation, then approve the plan.'],['Vendors get their own answers.','Every vendor sees their own stock, parcel progress and doorstep proof. You spend less time explaining what happened to an order.'],['Cash doesn’t disappear into the day.','Track rider cash held, handed in and checked. Verify payments and record vendor settlements with a per-order breakdown.'],['One team. A record of everything.','Invite office teammates, share announcements and search day records. Stock changes, payments and deliveries stay attached to the people who made them.']],quote:'Your business should grow.<br>The back-and-forth shouldn’t.',checks:['Company dashboard and Ada','Vendor and rider invitations','Stock and rider allocation','WhatsApp inbox with office takeover','Payment verification and day records']},
 '/for-vendors':{role:'vendor',label:'For vendors',title:'You sent the goods.<br>Stay in the know.',intro:'Your products are out of your hands. Their progress shouldn’t be. Follow your stock, every drop and what you’re owed—without calling the office.',action:'Join with an invite code',href:'/join?as=vendor',sub:'From your shelf to their doorstep. You can see it.',features:[['Send orders the way you already do.','Use your vendor portal or send orders to Ada on WhatsApp. Labelled lines, lists and pasted messages are read and checked. Missing details are flagged for a fix.'],['Your stock, kept straight.','See units given, delivered and left. Know what is with riders and what is still in the warehouse. Only a confirmed delivery reduces what’s left.'],['The proof arrives with the update.','When the rider confirms the drop, see the photo, recipient, time and payment. The company and your vendor view update from the same delivery record.'],['See what you’re owed.','Follow the amount collected, the company’s delivery fee and your payable balance. Check each payout instead of reconstructing a day from messages.'],['Your business stays yours.','Your login shows only your products, orders, deliveries and money. Invite your own team to your vendor view without exposing another vendor’s sales.']],quote:'Less “has it arrived?”<br>More getting on with business.',checks:['Your stock and order view','Live parcel progress and doorstep proof','Balance and payout records','Orders through portal or WhatsApp','Your own team logins']},
 '/for-riders':{role:'rider',label:'For dispatch riders',title:'A clear next stop.<br>A better day’s ride.',intro:'Your batch, your route and what you’ll earn. Ada keeps the next drop clear so you can focus on the road ahead.',action:'Join with an invite code',href:'/join?as=rider',sub:'From a new batch to your last hand-in.',features:[['Know the batch before you take it.','A new offer shows your stops, route and pay. Accept it, or turn it down with a reason. The office sees your response and can plan from there.'],['One drop at a time.','Collect your products at the office and work through your stops in riding order. Customer details and the amount to collect stay with the drop.'],['Confirm at the doorstep.','Take a photo, enter the recipient, the amount and the payment method. Ada stamps the time. If something goes wrong, record the problem.'],['WhatsApp comes along for the ride.','Reply YES, COLLECTED, ARRIVED or PROBLEM to Ada. ARRIVED opens a secure link to your photo and payment step. Supported everyday replies work in Pidgin too.'],['Know your earnings. Keep your hand-ins clear.','See your delivered drops and daily pay. Your wallet separates cash with you, handed in and checked by the office. Your work stays on record.']],quote:'Your next drop is clear.<br>Your day’s work is on record.',checks:['Clear batch offers and riding order','Doorstep photo and payment capture','WhatsApp replies and office messages','Daily earnings and rider wallet','History and rider levels']}
};
function audiencePage(d){return `<section class="wrap page-hero split"><div><span class="eyebrow">${d.label}</span><h1>${d.title}</h1><p class="lead">${d.intro}</p><div class="actions">${btn(d.action,d.href)}${link('Try your view',`/demo?role=${d.role}`)}</div></div><div class="hero-portrait ${d.role}">${photo('','Illustrative campaign scene for '+d.label,d.role==='company'?'delivery-day-ada.webp':d.role==='rider'?'delivery-day-rider.webp':'delivery-day-stock.webp')}</div></section><nav class="wrap page-subnav" aria-label="On this page"><a href="#everyday">Your everyday work</a><a href="#your-view">Your view</a><a href="#questions">Questions</a></nav><section id="everyday" class="section-tight wrap role-detailed"><span class="eyebrow">Built around your day</span><h2>${d.sub}</h2><div class="feature-rows">${d.features.map(([t,p],i)=>`<article class="feature-row"><span>0${i+1}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="statement" style="margin-top:65px"><div class="wrap"><h2>${d.quote}</h2></div></section><section id="your-view" class="section wrap"><div class="editorial-split"><div class="editorial-text"><span class="eyebrow">Your own login. Your own view.</span><h2>${d.role==='company'?'Your whole business,<br>on one screen.':d.role==='vendor'?'Your parcels.<br>Your peace of mind.':'Your day,<br>in your pocket.'}</h2><div style="margin-top:30px">${list(d.checks)}</div>${link('Try the interactive demo',`/demo?role=${d.role}`)}${d.role!=='company'?'<p class="bordered-note">Your delivery company invites you. Ask the office for your personal invite code or link. Vendors and riders join through their company; this is not an independent rider marketplace.</p>':''}</div><div class="media-sheet ${d.role==='company'?'night':''}">${d.role==='company'?windowPreview():d.role==='vendor'?proofCard():waPhone()}</div></div></section><section id="questions" class="section-tight wrap"><div class="faq-layout"><h2>Good to know<br>before you join.</h2>${faqMarkup(d.role==='company'?[faq[0],faq[2],faq[7]]:d.role==='vendor'?[faq[0],faq[4],faq[6]]:[faq[0],faq[1],faq[5]])}</div></section>${closing()}`}
function howPage(){const steps=[['Stock arrives. Everyone sees it.','The office records the vendor’s products, quantity and exact unit price. The vendor sees their stock immediately.','box','40 GlowSkin serums × ₦12,500 each'],['The orders find their shape.','Vendors submit orders through the portal or on WhatsApp. Ada reads the details and sets incomplete orders aside to fix. No physical address means no dispatch.','chat','Missing phone? Flag it. Unknown product? Check it.'],['Ada drafts. You decide.','Ask Ada to dispatch. It matches stock and open orders, groups rider batches by area and daily load, totals the amounts to collect and drafts messages. You review and approve.','spark','Draft → review → Approve & send'],['Riders accept and collect.','Each rider gets a batch offer in the app or on WhatsApp. They accept, collect the stock at the office and start their drops. Turned-down batches return to the office’s attention.','bike','Clear stops, route and pay, before the rider accepts.'],['The doorstep becomes a record.','The rider captures the photo, recipient, amount and payment method. The time is stamped. The office and relevant vendor see the same delivered record.','camera','Photo + recipient + time + cash, transfer or POS'],['Stock moves. Money gets checked.','Delivered units leave the left count. The rider hands in cash, the office verifies payments and records each vendor’s payout. A delivery and a verified payment are separate events.','wallet','Received − delivered = left. Every naira has its own record.'],['Tomorrow, you can look back.','Open the calendar and choose the day. Review the drops, photos, stock, money and chats. Each role sees only their own part.','calendar','The day ends. Its record stays.']];return `<section class="wrap page-hero"><span class="eyebrow">How Ada works</span><h1>From “stock is here”<br>to “day is done”.</h1><p class="lead">One connected journey for the office, your vendors and your riders. Here’s what a day on Ada looks like.</p><div class="actions">${btn('Try a sample day','/demo')}${link('Meet Ada','/ada')}</div></section><section class="wrap section-tight"><div class="story-steps">${steps.map(([t,p,i,a],n)=>`<article class="story-step"><span>0${n+1}</span><div><h3>${t}</h3><p>${p}</p><div class="tiny-art">${icon(i)}${a}</div></div></article>`).join('')}</div></section>${closing()}`}
function adaPage(){return `<section class="wrap page-hero"><span class="eyebrow">Meet Ada · Your dispatch assistant</span><h1>You say what came in.<br>Ada plans what ${wave('goes out.')}</h1><p class="lead">Stock updates. Pasted orders. Rider batches. One plain conversation, with your team always in control.</p><div class="actions">${btn('Try Ada below','#ada-playground')}${link('See the whole day','/how-it-works')}</div></section><section class="wrap section-tight" id="ada-playground"><div class="editorial-split"><div class="editorial-text"><h2>A conversation.<br>A plan.<br>Your approval.</h2><p class="lead" style="margin-top:25px">Try a sample prompt. Ada can prepare a dispatch plan, answer a stock question or flag an order that needs more information.</p>${list(['Read orders in different WhatsApp layouts','Match products, stock and rider allocation','See the numbers and messages before sending','Keep unusual money and stock changes under human control'])}<p class="small-note">This interactive preview uses fixed sample data. It does not send messages or change a live company’s records.</p></div><div class="playground"><div class="playground-head">${orb()}<div><h3>Let Ada help.</h3><span class="small-note">Sample operation · You approve every plan</span></div></div><div id="ada-replies"><div class="chat-bubble ada">Tell me what arrived, paste an order, or ask about your stock. I’ll prepare the next step for you to review.</div></div><form class="ada-input" id="ada-form"><input name="prompt" aria-label="Ask Ada a sample question" placeholder="Tell Ada what came in…" required maxlength="700"><button aria-label="Send sample prompt">${icon('send')}</button></form><div class="prompt-chips"><button data-prompt="dispatch">Plan today’s drops</button><button data-prompt="stock">How many serums are left?</button><button data-prompt="missing">Read an incomplete order</button></div></div></div></section><section class="wrap section"><span class="eyebrow">Helpful, with boundaries</span><h2>Ada does the legwork.<br>You have the last word.</h2><div class="feature-rows">${[['Reads. Doesn’t guess.','Missing phone, unknown product or an address that is really a phone number? Ada flags it. Incomplete orders wait under Orders to fix.'],['Plans around your people.','Ada uses area and remaining daily allocation to draft rider batches. A dispatcher can review the work before it becomes the day’s plan.'],['Messages, without losing the office.','Batches and updates go through your connected WhatsApp Business number. Staff can read along, step in and hand the conversation back to Ada.']].map(([t,p],i)=>`<article class="feature-row"><span>0${i+1}</span><h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section>${closing()}`}
function whatsappPage(){return `<section class="wrap page-hero"><span class="eyebrow">Ada on WhatsApp</span><h1>Your people are<br>already here.<br>So is ${wave('Ada.')}</h1><p class="lead">Keep the familiar conversation. Connect it to the stock, drops and money behind the day.</p><div class="actions">${btn('Explore the conversations','#conversations')}${link('Try the product demo','/demo')}</div></section><section class="wrap section-tight" id="conversations"><div class="editorial-split reverse"><div class="editorial-text"><div class="flow-switch" role="tablist" aria-label="WhatsApp conversation"><button role="tab" aria-selected="true" data-wa="rider">For riders</button><button role="tab" aria-selected="false" data-wa="vendor">For vendors</button></div><div id="wa-explanation"><h2>A batch comes in.<br>A YES gets it moving.</h2><p class="lead" style="margin-top:25px">Riders accept a batch, confirm collection and get the next drop. ARRIVED opens the photo and payment step. Simple replies keep the office informed.</p></div><div class="marquee-words"><span>YES</span><span>COLLECTED</span><span>ARRIVED</span><span>PROBLEM</span><span>BALANCE</span></div></div><div class="media-sheet" id="wa-phone-container">${waPhone()}</div></div></section><section class="statement" style="margin-top:60px"><div class="wrap"><h2>One inbox.<br>Every conversation.<br>A human, whenever needed.</h2><p>Office staff can read every rider and vendor chat, step in to pause Ada, and hand it back when they’re ready.</p></div></section><section class="wrap section"><div class="two-columns"><div><span class="eyebrow">Connect your company’s number</span><h3>Your WhatsApp Business.<br>Your relationships.</h3><p>Ada works with an official WhatsApp Business number through Meta Cloud API or Twilio. Business verification and approved templates may be needed before your company can start certain conversations.</p></div><div><span class="eyebrow">Explore before connecting</span><h3>Try the test line first.</h3><p>The company app includes a phone simulator. Explore rider and vendor conversations before connecting a real number. Nothing leaves the test line.</p>${link('See the company’s tools','/for-companies')}</div></div><div class="inline-callout">${icon('shield')}<p>WhatsApp is an operating channel, not a shortcut around proof or approval. A person approves the dispatch plan. Delivered payments stay unverified until the office checks them.</p></div></section>${closing()}`}
function proofPage(){return `<section class="wrap page-hero"><span class="eyebrow">Proof of delivery</span><h1>“It arrived.”<br>And here’s the ${wave('proof.')}</h1><p class="lead">The photo. The person. The minute. The payment. A delivery record the office and vendor can both see.</p><div class="actions">${btn('Confirm a sample delivery','/demo?role=rider')}${link('For vendors','/for-vendors')}</div></section><section class="wrap section-tight"><div class="editorial-split"><div class="editorial-text"><h2>One doorstep.<br>A complete record.</h2><div class="feature-rows">${[['Photo','Taken at the door and attached to the delivery.'],['Time + recipient','Ada is stamped to the minute, with who received it.'],['Payment captured','The exact amount and whether it was cash, transfer or POS.'],['Payment verified','The office checks the money separately, when it lands.']].map(([t,p],i)=>`<div class="feature-row" style="grid-template-columns:25px 1fr;gap:10px 20px"><span>0${i+1}</span><div><h3 style="font-size:24px">${t}</h3><p style="margin-top:10px;font-size:13px">${p}</p></div></div>`).join('')}</div></div><div class="media-sheet">${proofCard()}</div></div></section><section class="wrap section"><div class="chapter-head"><div><span class="eyebrow">Stock and money tell different stories</span><h2>Delivered is a fact.<br>Paid in is another.</h2></div><p>A vendor’s stock shouldn’t wait for a cash hand-in. A cash balance shouldn’t disappear when a rider completes the drop.</p></div>${stockExample()}<div class="inline-callout">${icon('shield')}<p>Each vendor sees only their own delivery records through their account and secure shared photo links. Photos stay attached to the company’s records. A rider can update their own drops, not another rider’s work.</p></div></section><section class="wrap section-tight"><div class="editorial-split reverse"><div class="editorial-text"><span class="eyebrow">When someone asks tomorrow</span><h2>The answer is<br>one day record away.</h2><p class="lead" style="margin-top:25px">See who collected what, who delivered it and when, plus the photos, money and that day’s conversation.</p>${link('Explore the day’s work','/how-it-works')}</div><div class="media-sheet night">${calendar()}</div></div></section><section class="section wrap">${faqMarkup([faq[3],faq[4],faq[5],faq[6]])}</section>${closing()}`}
function pricingPage(){return `<section class="wrap page-hero"><span class="eyebrow">Pricing</span><h1>One company.<br>Your whole operation.</h1><p class="lead">The delivery company gets Ada. Its vendors and riders join through its account.</p></section><section class="wrap section-tight"><div class="price-panel"><div class="price-left"><span class="eyebrow" style="color:#b5c0ed">Built around the company</span><h2>Start with the work.<br>Let’s find your fit.</h2><p>Pricing is being finalised. Start with the product and see how it fits your company’s everyday work. We’ll publish clear plans when they’re ready.</p><div class="actions">${btn('Get started free','/get-started','white')}</div><div style="margin-top:25px">${link('Book a walkthrough','/book-a-demo')}</div></div><div class="price-right"><h3>The operation, connected.</h3>${list(['Ada dispatch planning, with your approval','Your company dashboard and office teammates','Vendor portals and rider views','Stock, doorstep proof and payment records','WhatsApp tools for your connected business number','Calendar, history and day records'])}<p class="small-note">Vendors and riders use Ada as part of their company’s account. WhatsApp provider requirements and charges are separate from any future Ada pricing.</p></div></div></section><section class="section wrap"><div class="faq-layout"><h2>Clear answers.<br>Before you begin.</h2>${faqMarkup([faq[9],faq[0],faq[7],faq[8]])}</div></section>${closing()}`}
function questionsPage(){return `<section class="wrap page-hero"><span class="eyebrow">Questions & answers</span><h1>Good questions.<br>Straight answers.</h1><p class="lead">From your first company account to the final cash hand-in. The things you should know before you get started.</p></section><section class="section-tight wrap narrow">${faqMarkup()}</section><section class="section-tight wrap"><div class="inline-callout">${icon('chat')}<div><h4 style="margin-bottom:10px">Want to see your own workflow?</h4><p>Prepare a demo brief around your delivery areas, riders and everyday challenges.</p><div style="margin-top:18px">${link('Book a demo','/book-a-demo')}</div></div></div></section>${closing()}`}
function contactPage(){return `<section class="wrap page-hero"><span class="eyebrow">Book a demo</span><h1>Let’s talk about<br>your next ${wave('delivery day.')}</h1><p class="lead">A useful walkthrough starts with how your operation actually works.</p></section><section class="section-tight wrap"><div class="contact-grid"><div><h2>Your workflow.<br>Not a generic tour.</h2><p class="lead">Tell us what comes in, how many riders head out and what takes the most chasing. Build a demo brief around those details.</p><ul class="contact-list"><li>${icon('spark')}See how Ada drafts your day.</li><li>${icon('bike')}Walk through a rider’s batch.</li><li>${icon('camera')}Follow the proof back to the vendor.</li><li>${icon('wallet')}Close the loop on money and stock.</li></ul><div class="bordered-note">This preview prepares your demo brief in your browser. It does not send a request or book a meeting. You can review and download it before sharing.</div></div><div class="form-panel"><h3>What does your day look like?</h3><form id="demo-brief-form"><div class="form-grid"><label class="field">Your name<input name="name" autocomplete="name" required placeholder="Your name"></label><label class="field">Company name<input name="company" autocomplete="organization" required placeholder="Your delivery company"></label><label class="field full">Work email<input name="email" type="email" autocomplete="email" required placeholder="you@company.com"></label><label class="field">Riders in your operation<select name="riders"><option>1–5 riders</option><option>6–20 riders</option><option>21–50 riders</option><option>More than 50 riders</option></select></label><label class="field">Main delivery area<input name="area" required placeholder="e.g. Ikeja, Lagos"></label><label class="field full">What takes the most chasing?<textarea name="challenge" required placeholder="Orders, dispatch, stock, hand-ins… tell us about your day."></textarea></label></div><button class="btn" type="submit" style="margin-top:25px">Prepare my demo brief ${icon('arrow')}</button><p class="small-note">Your details stay in this browser. No account is created.</p></form><div id="brief-result" aria-live="polite"></div></div></div></section>${demoInvite()}`}
function getStartedPage(){return `<section class="wrap page-hero narrow"><span class="eyebrow">Your next delivery day starts here</span><h1>Find your<br>way ${wave('in.')}</h1><p class="lead">The company sets up the operation. Vendors and riders join with a personal invitation.</p><div class="setup-cards"><article class="setup-card featured">${icon('grid')}<h3>I run a delivery company.</h3><p>Bring your vendors, riders and office together. Start with your company’s own workspace.</p>${btn('Create a company account','/signup/company','white')}</article><article class="setup-card">${icon('team')}<h3>I have an invite.</h3><p>Your company invited you as a vendor, rider or teammate. Join with the code they sent.</p>${btn('Join with an invite code','/join','outline')}</article></div><div class="bordered-note">Just looking around? ${link('Try the sample operation','/demo')}<br><br>Already part of a company? <a href="/signin" style="color:var(--blue);text-decoration:underline">Sign in to Ada.</a></div></section>`}
const appOrigin=()=>{try{const v=window.DELIVERY_CONFIG?.appOrigin;return v?new URL(v).origin:''}catch{return ''}};
function appGate(kind){
 const origin=appOrigin(), isJoin=kind==='join', isSignup=kind==='signup';
 const title=isJoin?'Your invite.<br>Your place in the team.':isSignup?'A new day for<br>your delivery company.':'Welcome back.<br>Your day is waiting.';
 const dest=isJoin?'/join':isSignup?'/signup/company':'/signin';
 let code='';try{if(location.pathname.startsWith('/join/'))code=decodeURIComponent(location.pathname.slice(6));}catch{}
 const form=`<form id="join-form"><label class="field">Invite code<input name="code" value="${escapeHtml(code)}" placeholder="Enter the code from your office" required spellcheck="false" autocomplete="off" maxlength="80"></label><button class="btn" style="margin-top:20px">Continue to my company ${icon('arrow')}</button></form>`;
 const entrance=origin?(isJoin?form:btn(isSignup?'Continue to company signup':'Continue to sign in',origin+dest)):`<div class="connection-notice">Your live Ada account is separate from this marketing preview. The production app address hasn’t been connected here yet. No login details are collected on this page.</div><div class="actions">${btn('Explore the product demo','/demo')}${btn('See how joining works','/questions','outline')}</div>`;
 return `<section class="wrap page-hero narrow"><span class="eyebrow">${isJoin?'Join your company':isSignup?'Create your company account':'Sign in to Ada'}</span><h1 style="font-size:clamp(48px,6.2vw,88px)">${title}</h1><p class="lead">${isJoin?'Your office sends your personal invite code or link. It connects you to the right company and your own role.':isSignup?'Set up your company, choose your delivery areas, then invite your vendors and riders.':'Sign in through your company’s Ada app to open your real dashboard.'}</p><div style="max-width:600px;margin-top:35px">${entrance}<p class="bordered-note">${isJoin?'No invite yet? Ask the office to add you under Team and send your own code. Each vendor and rider gets their own login.':isSignup?'Vendors and riders don’t create a company account. They join an existing company through an invite.':'Forgot your password? Your company can send you a fresh invite to replace the old login.'}</p></div></section>${demoInvite()}`;
}

function privacyPage(){return `<section class="wrap page-hero narrow"><span class="eyebrow">Privacy & this preview</span><h1 style="font-size:clamp(50px,6vw,88px)">Clear about<br>what stays here.</h1><p class="lead">This is the Ada marketing website and an illustrative product demo.</p></section><article class="reading wrap"><h2>Sample data, not real deliveries</h2><p>The interactive demo uses fictional orders, riders, vendors and amounts. It is not connected to a live company workspace. Demo progress is saved in this browser’s local storage so that company, vendor and rider views can show the same sample drop. Reset demo clears that sample progress.</p><h2>Photos in the demo</h2><p>A photo you choose in the sample rider flow is processed in your browser to preview the proof step. It is not uploaded to a server or saved with your account. Use the sample photo if you prefer. The website’s campaign imagery is AI-generated and illustrative; it is not a photograph of a customer, employee or completed delivery.</p><h2>Your demo brief</h2><p>The Book a demo page prepares text in your browser. It does not send an email or book a meeting. You can download the brief and decide whether and where to share it. Form details are not sent by this site.</p><h2>Company accounts</h2><p>Real company sign-in, signup and invitations belong to the production Ada application. This site links directly to the production application for sign-in, company signup and invitations. This preview does not collect passwords or create operational accounts.</p><h2>The real product</h2><p>In the Ada product, the company, each vendor and each rider have separate access. Vendors see their own stock, deliveries and money; riders see their own drops. A published product privacy policy and service terms should be reviewed before any public account launch.</p><div class="actions"><button class="btn outline" data-action="reset-demo">Reset this browser’s demo ${icon('reset')}</button>${btn('Back to Ada','/')}</div></article>`}
const demoKey='delivery-marketing-demo-v1';
const blankDemo=()=>({accepted:false,delivered:false,verified:false,amount:25000,method:'Cash',recipient:'Ada Eze',deliveredAt:null,hasPhoto:false});
let demoState;try{demoState={...blankDemo(),...JSON.parse(localStorage.getItem(demoKey)||'{}')}}catch{demoState=blankDemo()}
let selectedRole=new URLSearchParams(location.search).get('role')||'company';if(!['company','vendor','rider'].includes(selectedRole))selectedRole='company';
let samplePhotoReady=false;let chosenPhoto='';
function saveDemo(){try{localStorage.setItem(demoKey,JSON.stringify(demoState));}catch{showToast('Your browser blocked demo storage. You can still try this view; cross-tab updates may be unavailable.');}}
function demoPage(){return `<section class="wrap page-hero"><span class="eyebrow">Interactive product demo · Sample data</span><h1 style="font-size:clamp(50px,6.3vw,88px)">The same delivery.<br>A view for ${wave('everyone.')}</h1><p class="lead">Accept the batch as a rider. Add the proof. Switch to the office or vendor and see the record update.</p></section><section class="wrap section-tight" style="padding-top:10px"><div class="demo-toolbar"><div class="demo-tabs" role="tablist" aria-label="Demo role">${['company','vendor','rider'].map(r=>`<button role="tab" aria-selected="${selectedRole===r}" data-role="${r}" tabindex="${selectedRole===r?0:-1}" aria-controls="demo-view">${r[0].toUpperCase()+r.slice(1)}</button>`).join('')}</div><button class="reset-button" data-action="reset-demo">${icon('reset')}Reset demo</button></div><div class="demo-workspace"><aside class="demo-sidebar"><div>${logo()}</div><ul><li class="active">${icon('grid')}Today</li><li>${icon('box')}Deliveries</li><li>${icon('store')}Vendors & stock</li><li>${icon('bike')}Riders</li><li>${icon('chat')}WhatsApp</li><li>${icon('calendar')}Day records</li></ul><p class="small-note">Illustrative interface<br>Sample operation<br>No messages are sent.</p></aside><div class="demo-content" id="demo-view" role="tabpanel" aria-label="Sample role dashboard">${renderDemoView()}</div></div><div class="demo-hint">Try this in two tabs in the same browser: open the rider view in one and the company view in the other. Complete the sample drop and see both update. This preview stores sample progress only on this device; the live product shares changes through the company’s server.</div></section>${closing()}`}
function renderDemoView(){const d=demoState;if(selectedRole==='rider')return riderDemo();const vendor=selectedRole==='vendor';return `<div class="demo-content-head"><h3>${vendor?'GlowSkin’s day.':'Your day, in view.'}</h3><span class="live">Sample workspace</span></div><div class="demo-greeting"><small>${vendor?'YOUR VENDOR VIEW':'GOOD MORNING, GEORGE'}</small>${vendor?`<span>You’ve given us</span> 40 serums.<br>${d.delivered?24:22} delivered. <span>${d.delivered?16:18} left.</span>`:`<span>You’ve sold</span> ₦${(1284000+(d.delivered?Number(d.amount):0)).toLocaleString('en-NG')}<br><span>and</span> ${d.delivered?310:312} units <span>are left.</span>`}</div><div class="demo-data-grid"><div><span>Delivered</span><strong>${vendor?(d.delivered?24:22):(d.delivered?25:24)}</strong></div><div><span>With riders</span><strong>${vendor?(d.delivered?4:6):(d.delivered?10:12)}</strong></div><div><span>${vendor?'Left':'Payment to verify'}</span><strong>${vendor?(d.delivered?16:18):(d.delivered&&!d.verified?'₦'+Number(d.amount).toLocaleString('en-NG'):'₦0')}</strong></div></div><div class="demo-delivery"><div><h4>Ada Eze · 2 GlowSkin serums</h4><p>Ikeja · Tunde Bakare · ₦${Number(d.delivered?d.amount:25000).toLocaleString('en-NG')}</p></div><span class="status ${!d.delivered?'blue':!d.verified?'amber':''}">${d.delivered?(d.verified?'Delivered · paid in':'Delivered · payment to verify'):(d.accepted?'Batch accepted':'Waiting for rider')}</span></div>${d.delivered?`<div style="margin-top:22px"><div class="demo-proof-image"><img src="${chosenPhoto||'/marketing/assets/delivery-day-rider.webp'}" alt="${chosenPhoto?'Your browser-local doorstep photo preview':'Illustrative sample doorstep proof'}"><small>${chosenPhoto?'Your selected photo · This tab only · Not uploaded':'Shared sample proof · Illustrative cartoon handover'}</small></div><div class="proof-lines"><div><span>Doorstep proof</span><b>Photo attached · ${new Date(d.deliveredAt).toLocaleTimeString('en-NG',{hour:'2-digit',minute:'2-digit'})}</b></div><div><span>Received by</span><b>${escapeHtml(d.recipient)}</b></div><div><span>Collected</span><b>₦${Number(d.amount).toLocaleString('en-NG')} · ${escapeHtml(d.method)}</b></div></div><div class="demo-action">${!vendor&&!d.verified?`<button class="btn blue" data-action="verify-demo">${icon('check')}Verify sample payment</button><small>Office checks that the money landed.<br>This button changes sample data only.</small>`:vendor?'<small>Your company verifies payment and records your payout. This view shows only GlowSkin’s records.</small>':'<span class="status">Sample payment verified by the office</span>'}</div></div>`:`<div class="demo-action"><button class="btn blue" data-role="rider">Open the rider’s view ${icon('arrow')}</button><small>Accept the sample batch and capture the proof.</small></div>`}<div class="ada-mini" style="font-size:12px;padding:12px;margin-top:28px">${orb()}<span>${d.delivered?(d.verified?'Ada: Delivery complete. The office has verified payment.':'Ada: Ada’s delivery is complete. Payment needs the office’s check.'):'Ada: The sample batch is ready for Tunde to accept.'}</span></div>`}
function riderDemo(){const d=demoState;if(!d.accepted)return `<div class="rider-demo"><div class="demo-content-head"><h3>Morning, Tunde.</h3><span class="live">On duty</span></div><div class="rider-offer"><span class="eyebrow" style="color:#b4c1f0;font-size:9px">New batch · Sample offer</span><h3>3 stops.<br>All around Ikeja.</h3><p>Your next batch is ready. Review the drops and collect at the office.</p><div class="draft-list"><div><b>3</b>drops</div><div><b>₦3,000</b>sample rider pay</div></div><button class="approve" data-action="accept-demo">Accept sample batch ${icon('arrow')}</button></div><div class="route-stop"><span>1</span><div><h4>Ada Eze · 5 Ajao Road</h4><p>Ikeja · 2 serums · ₦25,000 to collect</p></div></div><p class="small-note" style="margin-top:20px">Illustrative pay and data. This is not a live job offer.</p></div>`;if(d.delivered)return `<div class="rider-demo"><div style="text-align:center;padding:15px 0 25px"><span class="tick" style="display:inline-grid;place-items:center;width:54px;height:54px;border-radius:50%;background:#dff8ed;color:#07835e">${icon('check')}</span><h3 style="margin-top:20px">That drop is on record.</h3><p class="muted" style="font-size:13px;margin-top:15px">The sample office and vendor views now show the delivery. Payment stays unverified until the office checks it.</p></div>${list(['Doorstep photo attached','Recipient and timestamp captured',`₦${Number(d.amount).toLocaleString('en-NG')} collected · ${escapeHtml(d.method)}`])}<button class="btn blue" data-role="company" style="width:100%">See the company’s update ${icon('arrow')}</button><button class="btn outline" data-role="vendor" style="width:100%;margin-top:12px">See the vendor’s update ${icon('arrow')}</button></div>`;return `<div class="rider-demo"><div class="demo-content-head"><h3>Your next drop.</h3><span class="status blue">1 of 3</span></div><div class="route-stop"><span>${icon('pin')}</span><div><h4>Ada Eze</h4><p>5 Ajao Road, Ikeja · Sample customer</p></div></div><div class="proof-upload">${icon('camera')}<label for="proof-file">Add a doorstep photo</label><input type="file" id="proof-file" accept="image/*" capture="environment" aria-label="Choose a sample doorstep photo"><button class="sample-proof-btn" data-action="sample-photo">Use the sample photo instead</button><div id="photo-status" class="small-note" aria-live="polite" style="margin-top:10px">${samplePhotoReady?'Sample photo ready.':''}</div></div><form class="demo-form" id="delivery-proof-form"><label class="field">Received by<input name="recipient" value="Ada Eze" required maxlength="80"></label><div class="form-grid" style="grid-template-columns:1fr 1fr;gap:12px"><label class="field">Amount collected (₦)<input name="amount" type="number" min="0" step="1" value="25000" required></label><label class="field">Payment method<select name="method"><option>Cash</option><option>Transfer</option><option>POS</option></select></label></div><button class="btn blue" type="submit" style="width:100%">Confirm sample delivery ${icon('check')}</button><p class="small-note" id="proof-feedback" aria-live="polite">Demo only. Your selected photo is not uploaded.</p></form></div>`}
const pageMap={'/':{title:'Every delivery, live for everyone',render:home},'/how-it-works':{title:'How Ada works',render:howPage},'/ada':{title:'Meet Ada, your dispatch assistant',render:adaPage},'/whatsapp':{title:'Your people already live on WhatsApp',render:whatsappPage},'/proof-of-delivery':{title:'The photo. The time. The payment.',render:proofPage},'/pricing':{title:'Pricing for your delivery operation',render:pricingPage},'/questions':{title:'Questions & answers',render:questionsPage},'/book-a-demo':{title:'A walkthrough around your working day',render:contactPage},'/get-started':{title:'Find your way in',render:getStartedPage},'/signup/company':{title:'Create your company account',render:()=>appGate('signup')},'/join':{title:'Join your company',render:()=>appGate('join')},'/signin':{title:'Sign in',render:()=>appGate('signin')},'/demo':{title:'Try a delivery from all three sides',render:demoPage},'/privacy':{title:'Privacy & this preview',render:privacyPage}};
for(const [path,data] of Object.entries(audienceData))pageMap[path]={title:data.label,render:()=>audiencePage(data)};
let currentPath=(document.documentElement.dataset.marketingRoute||location.pathname).replace(/\/$/,'')||'/';if(currentPath.startsWith('/join/'))currentPath='/join';
function connectAppLinks(){if(!appOrigin())return;document.querySelectorAll('a[href]').forEach(a=>{const h=a.getAttribute('href');if(/^\/(?:signin(?:\?|$)|signup\/company(?:\?|$)|join(?:\/|\?|$))/.test(h)){a.href=appOrigin()+h;a.dataset.appRoute='true';}})}

function withStoryArtwork(markup,path){
 const art={
 '/how-it-works':['delivery-journey.webp','A vendor, dispatcher and courier connected through one cheerful parcel journey','wide'],
 '/ada':['delivery-day-ada.webp','A dispatcher checks a plan while cheerful parcels get ready for their drops'],
 '/pricing':['delivery-planning.webp','A vendor and dispatcher plan together with the smiling parcel character'],
 '/book-a-demo':['delivery-planning.webp','A logistics team discusses a delivery plan around a parcel table'],
 '/whatsapp':['delivery-parcel-mascot.webp','The smiling parcel character keeps everyone connected'],
 '/proof-of-delivery':['delivery-day-rider.webp','A courier and customer confirm a cheerful parcel handover'],
 '/questions':['delivery-parcel-mascot.webp','The cheerful parcel character is ready to help']
 }[path];
 if(!art)return markup;
 return markup.replace(/<section class="wrap page-hero">([\s\S]*?)<\/section>/,(_,copy)=>
  '<section class="wrap page-hero '+(art[2]==='wide'?'story-intro':'split story-hero')+'"><div class="story-hero-copy">'+copy+'</div><div class="page-story-art '+(art[2]==='wide'?'page-story-wide':'')+'"><img src="/marketing/assets/'+art[0]+'" alt="'+art[1]+'" width="1536" height="1024" decoding="async" fetchpriority="high"></div></section>');
}

function render(){document.body.className=currentPath==='/'?'home-page':'inner-page';const p=pageMap[currentPath];document.title=p?`${p.title} — Ada`:'Page not found — Ada';document.getElementById('app').innerHTML=header()+`<main id="main" tabindex="-1">${p?withStoryArtwork(p.render(),currentPath):`<section class="route-error"><h1>Wrong turn?</h1><p>Let’s get you back to the right delivery.</p>${btn('Back to Ada','/')}</section>`}</main>`+(currentPath==="/"?landingFooter():footer())+`<div class="toast" role="status" hidden></div>`;const meta=document.querySelector('meta[name="description"]');if(meta)meta.content=p?`${p.title}. Ada connects Nigerian logistics companies, vendors and dispatch riders with Ada, stock tracking, doorstep proof and payment records.`:'Ada website';connectAppLinks();}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function showToast(text){const t=document.querySelector('.toast');t.textContent=text;t.hidden=false;clearTimeout(window.deliveryToastTimer);window.deliveryToastTimer=setTimeout(()=>t.hidden=true,4500)}
function closeMenu(){document.querySelector('.mobile-menu')?.remove();document.getElementById('app').inert=false;document.body.classList.remove('menu-open');const b=document.querySelector('.menu-toggle');b?.setAttribute('aria-expanded','false');b?.focus()}
function openMenu(){document.body.classList.add('menu-open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','true');const d=document.createElement('div');d.className='mobile-menu';d.setAttribute('role','dialog');d.setAttribute('aria-modal','true');d.setAttribute('aria-label','Navigation');d.innerHTML=`<div class="mobile-top">${logo()}<button aria-label="Close navigation" data-action="close-menu">${icon('x')}</button></div><nav class="mobile-links">${routes.map(([t,h],i)=>`<a href="${h}" class="${i>2?'sub':''}">${t}</a>`).join('')}</nav><div class="actions">${btn('Get started free','/get-started','white')}${btn('Sign in','/signin','white')}</div>`;document.body.append(d);document.getElementById('app').inert=true;connectAppLinks();d.querySelector('button').focus()}
function updateDemo(){document.getElementById('demo-view').innerHTML=renderDemoView();document.querySelectorAll('[data-role][role=tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.role===selectedRole));b.tabIndex=b.dataset.role===selectedRole?0:-1;})}
function setDemoRole(role){selectedRole=role;history.replaceState(null,'',`/demo?role=${role}`);updateDemo()}
document.addEventListener('click',e=>{const menu=e.target.closest('.menu-toggle');if(menu){openMenu();return}const nav=e.target.closest('.nav-trigger');if(nav){const on=nav.getAttribute('aria-expanded')==='true';nav.setAttribute('aria-expanded',String(!on));nav.closest('.nav-item').classList.toggle('is-open',!on);return}const role=e.target.closest('[data-role]');if(role&&currentPath==='/demo'){setDemoRole(role.dataset.role);return}const prompt=e.target.closest('[data-prompt]');if(prompt){const samples={dispatch:'GlowSkin dropped 40 serums at ₦12,500 each. Dispatch today’s orders.',stock:'How many serums are left?',missing:'Deliver one serum to Kemi in Yaba. ₦12,500.'};const input=document.querySelector('#ada-form input');input.value=samples[prompt.dataset.prompt];document.getElementById('ada-form').requestSubmit();return}const wa=e.target.closest('[data-wa]');if(wa){const mode=wa.dataset.wa;document.querySelectorAll('[data-wa]').forEach(b=>b.setAttribute('aria-selected',String(b===wa)));document.getElementById('wa-phone-container').innerHTML=waPhone(mode);document.getElementById('wa-explanation').innerHTML=mode==='rider'?'<h2>A batch comes in.<br>A YES gets it moving.</h2><p class="lead" style="margin-top:25px">Riders accept a batch, confirm collection and get the next drop. ARRIVED opens the photo and payment step. Simple replies keep the office informed.</p>':'<h2>Your orders in.<br>Your answers back.</h2><p class="lead" style="margin-top:25px">Vendors send stock, paste orders and ask for their balance. Ada checks the details and shares delivery, failure and payout updates with the right vendor.</p>';return}const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='close-menu')closeMenu();if(action==='approve-preview'){a.closest('.chat-bubble').innerHTML='<span class="chat-label">SAMPLE PLAN APPROVED</span><div class="inline-success">3 rider batches prepared. In the live product, Ada would now save the plan and send the messages.</div>';showToast('Sample approved. No live stock changed and no messages were sent.')}if(action==='reset-demo'){demoState=blankDemo();samplePhotoReady=false;chosenPhoto='';saveDemo();if(currentPath==='/demo')updateDemo();showToast('Sample operation reset. No live records changed.')}if(action==='accept-demo'){demoState.accepted=true;saveDemo();updateDemo();showToast('Sample batch accepted. Add the doorstep proof next.')}if(action==='sample-photo'){if(chosenPhoto)URL.revokeObjectURL(chosenPhoto);chosenPhoto='';samplePhotoReady=true;document.getElementById('photo-status').innerHTML='<img src="/marketing/assets/delivery-day-rider.webp" alt="Illustrative sample doorstep proof" style="width:100%;height:130px;object-fit:cover;border-radius:9px;margin-bottom:10px">Sample illustration selected. Ready to confirm.';}if(action==='verify-demo'){demoState.verified=true;saveDemo();updateDemo();showToast('Sample payment verified. Stock count stays unchanged.')}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(document.querySelector('.mobile-menu'))closeMenu();document.querySelectorAll('.nav-item.is-open').forEach(item=>{item.classList.remove('is-open');const trigger=item.querySelector('.nav-trigger');trigger.setAttribute('aria-expanded','false');trigger.focus();});}if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)&&e.target.matches('[role=tab]')){const tabs=[...e.target.closest('[role=tablist]').querySelectorAll('[role=tab]')];const i=tabs.indexOf(e.target);const j=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();tabs[j].click();tabs[j].focus();}const m=document.querySelector('.mobile-menu');if(m&&e.key==='Tab'){const els=[...m.querySelectorAll('a,button')];const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('change',e=>{if(e.target.id==='proof-file'){const f=e.target.files[0];if(f){if(!f.type.startsWith('image/')){showToast('Please choose an image file.');return}if(chosenPhoto)URL.revokeObjectURL(chosenPhoto);chosenPhoto=URL.createObjectURL(f);samplePhotoReady=true;document.getElementById('photo-status').innerHTML='<img src="'+chosenPhoto+'" alt="Your selected browser-local photo" style="width:100%;max-height:170px;object-fit:cover;border-radius:9px;margin-bottom:10px">Your photo is ready in this tab. It will not be uploaded.';}}});
document.addEventListener('submit',e=>{if(e.target.id==='ada-form'){e.preventDefault();const input=e.target.elements.prompt;const value=input.value.trim();if(!value)return;const replies=document.getElementById('ada-replies');const v=value.toLowerCase();let response;if(/left|stock|serum.*\?/.test(v)&&!/dropped|dispatch/.test(v)){response='<span class="chat-label">Ada · SAMPLE STOCK</span>GlowSkin has 18 serums left: 6 with riders and 12 in the warehouse. 22 of the 40 received are delivered. Payment verification is tracked separately.'}else if(/phone|kemi|yaba|deliver one/.test(v)&&!v.includes('dispatch')){response='<span class="chat-label">Ada · NEEDS A FIX</span>I’ve kept this sample order under Orders to fix. Please add Kemi’s phone number and a real physical address before dispatch. I won’t guess the missing details.'}else if(/dispatch|dropped|plan/.test(v)){response='<span class="chat-label">Ada · DRAFT FOR YOUR REVIEW</span>In this sample: 40 serums received, 6 deliveries for 3 riders, ₦206,000 to collect. Review the stock, rider batches and messages before you approve.<div style="margin-top:20px"><button class="approve" data-action="approve-preview">Approve sample plan '+icon('arrow')+'</button></div>'}else{response='<span class="chat-label">Ada · SAMPLE ASSISTANT</span>This preview can show a dispatch plan, a stock balance or an incomplete order. Try one of the sample prompts below. The live Ada works with your company’s real stock, riders and orders.'}replies.innerHTML=`<div class="chat-bubble you">${escapeHtml(value)}</div><div class="chat-bubble ada">${response}</div>`;input.value='';return}if(e.target.id==='delivery-proof-form'){e.preventDefault();if(!samplePhotoReady){document.getElementById('proof-feedback').textContent='Add a photo or choose the sample photo before confirming.';showToast('A doorstep photo is needed. Use the sample photo to try it.');return}const fd=new FormData(e.target);demoState={...demoState,delivered:true,hasPhoto:true,deliveredAt:new Date().toISOString(),amount:Number(fd.get('amount')),recipient:String(fd.get('recipient')).trim(),method:String(fd.get('method'))};saveDemo();updateDemo();showToast('Sample delivery complete. Company and vendor views updated.');return}if(e.target.id==='demo-brief-form'){e.preventDefault();const fd=new FormData(e.target);const content=`Ada · DEMO BRIEF\n\nName: ${fd.get('name')}\nCompany: ${fd.get('company')}\nEmail: ${fd.get('email')}\nOperation: ${fd.get('riders')}\nDelivery area: ${fd.get('area')}\n\nWhat needs attention:\n${fd.get('challenge')}\n\nWalkthrough: Ada dispatch, rider batches, doorstep proof, stock and payment hand-ins.\n\nPrepared in the marketing preview. Not submitted or booked.`;const result=document.getElementById('brief-result');result.innerHTML=`<div class="demo-brief-result"><h4>Your brief is ready.</h4><p>${escapeHtml(content)}</p><button class="btn blue" id="download-brief">Download my brief ${icon('arrow')}</button><p class="small-note" style="margin:15px 0 0">Prepared, not sent. No meeting has been booked.</p></div>`;document.getElementById('download-brief').onclick=()=>{const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='ada-demo-brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),500)};result.tabIndex=-1;result.focus({preventScroll:true});result.scrollIntoView({behavior:'smooth',block:'center'});showToast('Your demo brief is ready to review. Nothing has been sent.');return}if(e.target.id==='join-form'){e.preventDefault();const code=e.target.elements.code.value.trim();if(appOrigin()&&code)location.href=appOrigin()+'/join/'+encodeURIComponent(code)}});
window.addEventListener('storage',e=>{if(e.key===demoKey){try{demoState={...blankDemo(),...JSON.parse(e.newValue||'{}')};if(currentPath==='/demo')updateDemo()}catch{}}});
render();
